<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Workspace;
use App\Models\CareerRecord;
use App\Models\CareerSkill;
use App\Models\CareerLearningSession;
use App\Services\CareerService;
use App\Services\Identity;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Carbon;
use Tests\TestCase;
class CareerTest extends TestCase {
 use RefreshDatabase;
 private function login(User $u): static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version,'workspace_id'=>Identity::personal($u)->id])->withoutVite();}
 private function data(array $extra=[]): array{return array_merge(['kind'=>'course','title'=>'Linux fundamentals','status'=>'active','details'=>['provider'=>'Example','progress'=>25]],$extra);}
 private function record(User $u,array $extra=[]): CareerRecord{$r=new CareerRecord($this->data($extra));$r->workspace_id=Identity::personal($u)->id;$r->version=1;$r->save();return $r;}
 private function skillData(array $extra=[]): array{return array_merge(['name'=>'Linux','category'=>'Infrastructure','current_level'=>2,'target_level'=>5],$extra);}
 public function test_guests_denied(): void{$this->get('/career')->assertRedirect('/login');$this->get('/career/skills')->assertRedirect('/login');$this->get('/career/learning')->assertRedirect('/login');}
 public function test_all_record_types_and_forms(): void{$u=User::factory()->create();$this->login($u);foreach(CareerService::TYPES as $kind=>$type){$this->get('/career/create?kind='.$kind)->assertOk();$this->post('/career',$this->data(['kind'=>$kind,'status'=>$type['states'][0],'details'=>[]]))->assertRedirect();}$this->assertSame(10,CareerRecord::count());$this->get('/career')->assertOk()->assertSee('Linux fundamentals');}
 public function test_course_progress_and_revision_stale_protection(): void{$u=User::factory()->create();$this->login($u)->post('/career',$this->data())->assertRedirect();$r=CareerRecord::firstOrFail();$this->get('/career/'.$r->id)->assertOk()->assertSee('25%');$this->get('/career/'.$r->id.'/edit')->assertOk();$this->put('/career/'.$r->id,$this->data(['version'=>1,'details'=>['progress'=>75]]))->assertRedirect();$this->assertSame(2,$r->fresh()->version);$this->assertSame(25,$r->revisions()->firstOrFail()->snapshot['details']['progress']);$this->put('/career/'.$r->id,$this->data(['version'=>1]))->assertSessionHasErrors('version');$this->put('/career/'.$r->id,$this->data(['version'=>2,'kind'=>'lab','details'=>[]]))->assertSessionHasErrors('kind');}
 public function test_invalid_fields_status_urls_and_progress(): void{$u=User::factory()->create();$this->login($u)->post('/career',$this->data(['details'=>['progress'=>101]]))->assertSessionHasErrors('details.progress');$this->post('/career',$this->data(['details'=>['url'=>'javascript:alert(1)']]))->assertSessionHasErrors('details.url');$this->post('/career',$this->data(['details'=>['unexpected'=>'x']]))->assertSessionHasErrors('details');$this->post('/career',$this->data(['status'=>'offer']))->assertSessionHasErrors('status');$this->assertSame(0,CareerRecord::count());}
 public function test_ielts_and_certification_validation(): void{$u=User::factory()->create();$this->travelTo(Carbon::parse('2026-11-27 12:00 UTC'));$this->login($u);$d=$this->data(['kind'=>'ielts','status'=>'completed','details'=>['section'=>'writing','score'=>6.5,'practice_date'=>'2026-11-27','target_band'=>7.5]]);$this->post('/career',$d)->assertRedirect();$d['details']['score']=6.3;$this->post('/career',$d)->assertSessionHasErrors('details.score');$d['details']['score']=10;$this->post('/career',$d)->assertSessionHasErrors('details.score');$this->post('/career',$this->data(['kind'=>'certification','status'=>'earned','details'=>['earned_date'=>'2026-11-27','expiry_date'=>'2026-11-26']]))->assertSessionHasErrors('details.expiry_date');}
 public function test_skill_matrix_crud_and_gap(): void{$u=User::factory()->create();$this->login($u)->post('/career/skills',$this->skillData())->assertRedirect();$s=CareerSkill::firstOrFail();$this->assertSame(3,$s->gap());$this->get('/career/skills')->assertOk()->assertSee('Gap 3');$this->post('/career/skills',$this->skillData())->assertSessionHasErrors('name');$this->put('/career/skills/'.$s->id,$this->skillData(['current_level'=>5]))->assertRedirect();$this->assertSame(0,$s->fresh()->gap());$this->post('/career/skills',$this->skillData(['current_level'=>6]))->assertSessionHasErrors('current_level');$this->delete('/career/skills/'.$s->id)->assertRedirect();$this->assertDatabaseMissing('career_skills',['id'=>$s->id]);}
 public function test_learning_local_date_daily_cap_and_link_retention(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->travelTo(Carbon::parse('2026-11-27 20:00 UTC'));$r=$this->record($u);$this->login($u);$d=['topic'=>'Practice','local_date'=>'2026-11-28','minutes'=>120,'career_record_id'=>$r->id];$this->post('/career/learning',$d)->assertRedirect();$this->get('/career/learning')->assertOk()->assertSee('2.00 hours');$this->post('/career/learning',array_merge($d,['minutes'=>1400]))->assertSessionHasErrors('minutes');$this->post('/career/learning',array_merge($d,['local_date'=>'2026-11-29']))->assertSessionHasErrors('local_date');$this->delete('/career/'.$r->id)->assertRedirect();$s=CareerLearningSession::firstOrFail();$this->assertNull($s->career_record_id);$this->delete('/career/learning/'.$s->id)->assertRedirect();$this->assertSame(0,CareerLearningSession::count());}
 public function test_cross_workspace_records_skills_and_learning_denied(): void{$u=User::factory()->create();$other=User::factory()->create();$r=$this->record($other,['title'=>'Hidden career record']);$this->travelTo(Carbon::parse('2026-11-27 12:00 UTC'));$this->login($other)->post('/career/skills',$this->skillData())->assertRedirect();$this->post('/career/learning',['topic'=>'Private study','local_date'=>'2026-11-27','minutes'=>30])->assertRedirect();$s=CareerSkill::firstOrFail();$l=CareerLearningSession::firstOrFail();Identity::personal($other)->members()->attach($u->id,['role'=>'admin']);$this->login($u)->get('/career?q=Hidden')->assertOk()->assertDontSee('Hidden career record');$this->get('/career/'.$r->id)->assertNotFound();$this->put('/career/'.$r->id,$this->data(['version'=>1]))->assertNotFound();$this->delete('/career/'.$r->id)->assertNotFound();$this->put('/career/skills/'.$s->id,$this->skillData())->assertNotFound();$this->delete('/career/skills/'.$s->id)->assertNotFound();$this->delete('/career/learning/'.$l->id)->assertNotFound();$this->post('/career/learning',['topic'=>'Study','local_date'=>'2026-11-27','minutes'=>30,'career_record_id'=>$r->id])->assertSessionHasErrors('career_record_id');}
 public function test_business_workspace_denied(): void{$u=User::factory()->create();$w=Workspace::create(['owner_id'=>$u->id,'name'=>'Business','type'=>'business']);$this->login($u)->withSession(['workspace_id'=>$w->id])->get('/career')->assertForbidden();$this->get('/career/skills')->assertForbidden();$this->get('/career/learning')->assertForbidden();}
 public function test_dashboard_and_safe_rendering(): void{$u=User::factory()->create();$r=$this->record($u,['title'=>'<script>alert(1)</script>']);$this->login($u)->get('/career/'.$r->id)->assertOk()->assertDontSee('<script>alert(1)</script>',false)->assertSee('&lt;script&gt;alert(1)&lt;/script&gt;',false)->assertHeader('Cache-Control','no-store, private');$this->get('/dashboard')->assertOk()->assertSee('Active courses')->assertSee('Learning hours this month');}
}
